input.command:
$jsonl = Get-Content "d:\Vs_workplace\Java_project\TDD_TV_01\prompting\transcript_raw.jsonl" -Encoding UTF8
$sb = New-Object System.Text.StringBuilder
[void]$sb.AppendLine("# TDD_TV_01 Cursor Session Transcript")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("| 항목 | 값 |")
[void]$sb.AppendLine("|------|-----|")
[void]$sb.AppendLine("| Session ID | 3b7d5ee7-d341-4044-811c-f29bda2a0a36 |")
[void]$sb.AppendLine("| Export 일시 | $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') |")
[void]$sb.AppendLine("| 프로젝트 | TDD_TV_01 |")
[void]$sb.AppendLine("| 브랜치(작업) | prompting |")
[void]$sb.AppendLine("")
$turn = 0
foreach ($line in $jsonl) {
  if ([string]::IsNullOrWhiteSpace($line)) { continue }
  $obj = $line | ConvertFrom-Json
  $role = $obj.role
  if ($role -eq 'user') {
    $turn++
    [void]$sb.AppendLine("---")
    [void]$sb.AppendLine("")
    [void]$sb.AppendLine("## Turn $turn — User")
    [void]$sb.AppendLine("")
    foreach ($c in $obj.message.content) {
      if ($c.type -eq 'text') {
        $t = $c.text -replace '(?s)^<user_query>\s*', '' -replace '(?s)\s*</user_query>\s*$', ''
        [void]$sb.AppendLine($t.Trim())
        [void]$sb.AppendLine("")
      }
    }
  } elseif ($role -eq 'assistant') {
    [void]$sb.AppendLine("### Assistant")
    [void]$sb.AppendLine("")
    $hasText = $false
    foreach ($c in $obj.message.content) {
      if ($c.type -eq 'text') {
        $t = $c.text
        if ($t -and $t -ne '[REDACTED]' -and $t -notmatch '^\[REDACTED\]$') {
          $hasText = $true
          [void]$sb.AppendLine($t.Trim())
          [void]$sb.AppendLine("")
        }
      } elseif ($c.type -eq 'tool_use') {
        $name = $c.name
        $inp = ($c.input | ConvertTo-Json -Compress -Depth 3)
        if ($inp.Length -gt 200) { $inp = $inp.Substring(0, 200) + '...' }
        [void]$sb.AppendLine("- **Tool**: ``$name`` — ``$inp``")
      }
    }
    if (-not $hasText) {
      [void]$sb.AppendLine("_(응답 본문은 세션 로그에서 축약됨. 도구 호출 위 목록 참고.)_")
      [void]$sb.AppendLine("")
    }
  }
}
# Current turn - user request for export (may not be in jsonl yet)
[void]$sb.AppendLine("---")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("## Turn $($turn+1) — User (export 요청)")
[void]$sb.AppendLine("")
[void]$sb.AppendLine("현재까지의 prompt 를 prompting 폴더에 export transcript 해줘")
[void]$sb.AppendLine("")
$sb.ToString() | Set-Content "d:\Vs_workplace\Java_project\TDD_TV_01\prompting\transcript_export.md" -Encoding UTF8
